from collections import Counter, deque
def dist_to_component(g, r, c, cs):
    # BFS from multi-cell comps, return min dist to any multi-cell comp cell
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; d=-1e9
    q=deque()
    for b_ in cs:
        if len(b_['cells'])<=1: continue
        for x,y in b_['cells']:
            seen[x][y]=True; d=max(d,(x+r)**2+(y+c)**2)
            q.append((x,y))
    # better: multi-source BFS distances
    dist=[[float('inf')]*w for _ in range(h)]
    q=deque()
    for b_ in cs:
        if len(b_['cells'])<=1: continue
        for x,y in b_['cells']:
            dist[x][y]=0; q.append((x,y))
    while q:
        x,y=q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and dist[nx][ny]>dist[x][y]+1:
                dist[nx][ny]=dist[x][y]+1; q.append((nx,ny))
    return dist[r][c]
