    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; res=[]
    for r_ in range(h):
        for c_ in range(w):
            if g[r_][c_]!=bg and not seen[r_][c_]:
                col=g[r_][c_]; st=[(r_,c_)]; cells=set(); seen[r_][c_]=True
                while st:
                    x,y=st.pop(); cells.add((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and not seen[nx][ny] and g[nx][ny]==col:
                            seen[nx][ny]=True; st.append((nx,ny))
                res.append({'col':col,'cells':set(cells),'n':len(cells)})
    return res
def f_nearestcell(g):
    h,w=len(g),len(g[0]); bgval=Counter(x for rr in g for x in rr).most_common(1)[0][0]
    out=[row[:] for row in g]
    singles=[p for p in comps_of(g,bgval) if len(p['cells'])==1]
    for q in singles:
        r,c=min(q['cells']); best=None
        for i,row in enumerate(g):
            for j,x in enumerate(row):
                if x!=bgval:
                    dd=max(abs(i-r),abs(j-c))
                    if best is None or dd<best[0] or (dd==best[0] and x<best[1]):
                        best=(dd,x)
        out[r][c]=best[1] if best else bgval
    return out
for i in range(1,9):
    gi=G[f'Demo pair {i} input']; go=G[f'Demo pair {i} output']
    pred=f_nearestcell(gi); b=sum(pred[r][c]!=go[r][c] for r in range(len(pred)) for c in range(len(pred[0])))
    print(i,b)
